package com.smartfitagent.ai;
public final class AiClientFactory { private AiClientFactory(){} public static AiClient create(){String provider=System.getenv().getOrDefault("AI_PROVIDER","mock"); String key=System.getenv().getOrDefault("AI_API_KEY",""); if(key.isBlank()||provider.equalsIgnoreCase("mock"))return new MockAiClient(); String model=System.getenv().getOrDefault("AI_MODEL", provider.equalsIgnoreCase("deepseek")?"deepseek-chat":provider.equalsIgnoreCase("qwen")?"qwen-plus":provider.equalsIgnoreCase("kimi")?"moonshot-v1-8k":"gpt-compatible"); String url=System.getenv().getOrDefault("AI_BASE_URL", provider.equalsIgnoreCase("deepseek")?"https://api.deepseek.com/chat/completions":provider.equalsIgnoreCase("qwen")?"https://dashscope.aliyuncs.com/compatible-mode/v1/chat/completions":provider.equalsIgnoreCase("kimi")?"https://api.moonshot.cn/v1/chat/completions":""); return new OpenAiCompatibleClient(provider,url,key,model);} }
